const $=s=>document.querySelector(s),app=$('#app'),KEY='mathGarden2';
let data;try{data=JSON.parse(localStorage.getItem(KEY))}catch{}data=data&&Array.isArray(data.sessions)&&Array.isArray(data.mistakes)?data:{sessions:[],mistakes:[],level:'basic'};
const names={add:'덧셈',sub:'뺄셈',mul:'구구단',clock:'시계 읽기'},icons={add:'＋',sub:'−',mul:'×',clock:'◷'};
const today=()=>new Date().toLocaleDateString('sv-SE'),save=()=>{try{localStorage.setItem(KEY,JSON.stringify(data))}catch{$('#storageNotice')?.remove();app.insertAdjacentHTML('beforeend','<p id="storageNotice" class="notice">브라우저에서 저장을 허용하지 않아 이번 기록을 보관할 수 없어요.</p>')}};
let queue=[],index=0,score=0,answered=false,review=false,first=true;
function home(){let days=new Set(data.sessions.map(x=>x.day));app.innerHTML=`<section class="hero"><div class="eyebrow">MY LITTLE MATH GARDEN</div><h1>오늘도 생각의 씨앗을<br>하나 심어 볼까요?</h1><p>하루 10분, 차근차근 자라는 수학 자신감.<br>나만의 속도로 즐겁게 시작해요!</p><div class="garden" aria-hidden="true"><span class="sun">☀</span><div class="stem"></div><div class="leaf"></div><div class="leaf right"></div><div class="pot"></div><span class="spark">✧</span></div></section><section class="stats" aria-label="학습 요약"><div class="stat"><strong>⭐ ${data.sessions.reduce((s,x)=>s+x.score,0)}</strong><span>모은 별</span></div><div class="stat"><strong>🌱 ${days.size}일</strong><span>함께 자란 날</span></div><div class="stat"><strong>${data.sessions.filter(x=>x.day===today()).length}번</strong><span>오늘의 도전</span></div></section><div class="sectionhead"><h2>어떤 씨앗을 심어 볼까요?</h2><span>한 번에 5문제 · 시간 제한 없이</span></div><div class="setting"><label for="level">문제 난이도 </label><select id="level"><option value="basic">새싹 · 기초</option><option value="challenge">나무 · 도전</option></select></div><div class="cards">${Object.keys(names).map((k,i)=>`<button class="card" data-topic="${k}"><span class="icon">${icons[k]}</span><h3>${names[k]}</h3><p>${['수를 모아 더 크게!','남은 수를 알아봐요','같은 수끼리 묶어 봐요','몇 시 몇 분일까요?'][i]}</p><b>학습 시작 <span aria-hidden="true">↗</span></b></button>`).join('')}</div><div class="review"><div><strong>🍃 한 번 더, 쑥쑥 자라요</strong><p>틀렸던 문제 ${data.mistakes.length}개를 천천히 다시 풀어요.</p></div><button class="secondary" id="review" ${data.mistakes.length?'':'disabled'}>다시 풀기 →</button></div>`;$('#level').value=data.level;$('#level').onchange=e=>{data.level=e.target.value;save()};document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>start(b.dataset.topic));$('#review').onclick=()=>start('review')}
const rand=(a,b)=>Math.floor(Math.random()*(b-a+1))+a;
function make(topic){let a,b,answer,label,hint,svg='',hard=data.level==='challenge';if(topic==='add'){a=rand(11,hard?89:45);b=rand(2,hard?99-a:Math.min(9,49-a));answer=a+b;label=`${a} + ${b} = ?`;let tens=Math.floor(a/10)*10,ones=a%10;hint=`${a}는 ${tens}과 ${ones}로 나눌 수 있어요. ${ones} + ${b} = ${ones+b}, 여기에 ${tens}을 더하면 ${answer}예요.`}if(topic==='sub'){a=rand(12,hard?99:49);b=hard?rand(2,a-1):rand(1,a%10||1);answer=a-b;label=`${a} − ${b} = ?`;hint=`${a}에서 ${b}만큼 뒤로 가면 ${answer}예요. 확인해 볼까요? ${answer} + ${b} = ${a}!`}if(topic==='mul'){a=rand(2,hard?9:5);b=rand(1,9);answer=a*b;label=`${a} × ${b} = ?`;hint=`${a}개씩 ${b}묶음이에요. ${Array(b).fill(a).join(' + ')} = ${answer}예요.`}if(topic==='clock'){a=rand(1,12);b=hard?rand(0,11)*5:[0,30][rand(0,1)];answer=a*60+b;label='몇 시 몇 분일까요?';hint=`짧은 바늘은 ${a}시를, 긴 바늘은 ${b}분을 나타내요. 숫자 한 칸은 5분이에요.`;svg=clock(a,b)}return {topic,answer,label,hint,svg,key:topic+':'+a+':'+b}}
function clock(h,m){let hand=(angle,len,color,width)=>{let r=(angle-90)*Math.PI/180;return `<line x1="100" y1="100" x2="${100+Math.cos(r)*len}" y2="${100+Math.sin(r)*len}" stroke="${color}" stroke-width="${width}" stroke-linecap="round"/>`};return `<svg class="clock" viewBox="0 0 200 200" role="img" aria-label="시간을 보고 답을 골라 주세요"><circle cx="100" cy="100" r="95" fill="#fbfbf5" stroke="#d4dec8" stroke-width="5"/>${Array.from({length:12},(_,i)=>{let n=i+1,r=(n*30-90)*Math.PI/180;return `<text x="${100+Math.cos(r)*77}" y="${106+Math.sin(r)*77}" text-anchor="middle" font-size="17" fill="#426048">${n}</text>`}).join('')}${hand(h*30+m*.5,45,'#315e43',7)}${hand(m*6,65,'#b58748',4)}<circle cx="100" cy="100" r="6" fill="#315e43"/></svg>`}
function start(topic){review=topic==='review';queue=review?data.mistakes.slice(0,5).map(x=>({...x})):Array.from({length:5},()=>make(topic));index=score=0;show()}
const fmt=(q,n)=>q.topic==='clock'?`${Math.floor(n/60)}시 ${n%60}분`:n;
function show(){answered=false;first=true;let q=queue[index];let opts=new Set([q.answer]);if(q.topic==='clock'){while(opts.size<4){let h=rand(1,12),m=rand(0,11)*5;opts.add(h*60+m)}}else{while(opts.size<4)opts.add(Math.max(0,q.answer+rand(-9,9)))}opts=[...opts].sort(()=>Math.random()-.5);app.innerHTML=`<section class="panel"><div class="quiztop"><button class="back" id="back">← 정원으로</button><b>${review?'다시 풀기':names[q.topic]} · ${index+1} / ${queue.length}</b></div><div class="progress"><div style="width:${index/queue.length*100}%"></div></div><p>천천히 생각해도 괜찮아요 🌱</p>${q.svg||''}<div class="question">${q.label}</div><div class="options">${opts.map(n=>`<button class="option" data-answer="${n}">${fmt(q,n)}</button>`).join('')}</div><div class="feedback" aria-live="polite"></div><button class="primary next" id="next" hidden>다음 문제 →</button></section>`;$('#back').onclick=home;document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer),b));$('#next').onclick=()=>{index++;index===queue.length?finish():show()}}
function answer(n,b){if(answered)return;let q=queue[index];if(n!==q.answer){first=false;b.classList.add('wrong');b.disabled=true;$('.feedback').innerHTML=`<strong>조금만 더 생각해 볼까요? 🌱</strong>${q.hint}<br>맞는 답을 다시 골라 주세요.`;if(!data.mistakes.some(x=>x.key===q.key)){data.mistakes.push(q);save()}return}answered=true;b.classList.add('correct');document.querySelectorAll('[data-answer]').forEach(x=>x.disabled=true);if(first){score++;data.mistakes=data.mistakes.filter(x=>x.key!==q.key);save()}$('.feedback').innerHTML=`<strong>${first?'잘했어요! 별 하나가 자랐어요 ⭐':'끝까지 도전했어요! 다음에는 혼자서도 할 수 있어요 🌿'}</strong>${q.hint}`;$('#next').hidden=false;$('#next').textContent=index===queue.length-1?'오늘의 결과 보기 →':'다음 문제 →'}
function finish(){data.sessions.push({day:today(),score,total:queue.length,topic:review?'review':queue[0].topic});save();app.innerHTML=`<section class="panel"><div class="badge">🌻</div><div class="eyebrow">TODAY’S LITTLE GROWTH</div><h1>오늘도 한 뼘 자랐어요!</h1><p>${queue.length}문제를 끝까지 풀었어요. 정말 수고했어요.</p><div class="summary"><h2>⭐ 별 ${score}개를 모았어요</h2><p>첫 번째에 스스로 맞힌 문제 ${score} / ${queue.length}개<br>도움이 필요했던 문제는 다시 풀기에 모아 두었어요.</p></div><button class="primary" id="home">정원으로 돌아가기</button></section>`;$('#home').onclick=home}
function records(){let days=new Set(data.sessions.map(x=>x.day));app.innerHTML=`<section class="panel"><button class="back" id="back">← 정원으로</button><div class="badge">🌳</div><h1>차곡차곡, 나의 성장</h1><p>지금까지 ${days.size}일 동안 ${data.sessions.length}번 도전했어요.</p><div class="history">${Array.from({length:7},(_,i)=>{let d=new Date();d.setDate(d.getDate()-6+i);let key=d.toLocaleDateString('sv-SE');return `<div class="day ${days.has(key)?'done':''}">${d.getMonth()+1}/${d.getDate()}<br>${days.has(key)?'🌱':'·'}</div>`}).join('')}</div><div class="summary">풀어 본 문제 <b>${data.sessions.reduce((s,x)=>s+x.total,0)}개</b><br>모은 별 <b>${data.sessions.reduce((s,x)=>s+x.score,0)}개</b><br>다시 연습할 문제 <b>${data.mistakes.length}개</b></div><p>다른 기기나 브라우저에는 기록이 이어지지 않아요.</p><button class="primary" id="home">오늘도 학습하기</button><br><button class="reset" id="reset">이 기기의 학습 기록 지우기</button></section>`;$('#back').onclick=$('#home').onclick=home;$('#reset').onclick=()=>{if(confirm('모은 별과 학습 기록을 모두 지울까요? 이 작업은 되돌릴 수 없어요.')){data={sessions:[],mistakes:[],level:'basic'};save();records()}}}
$('#records').onclick=records;$('.brand').onclick=e=>{e.preventDefault();home()};home();
